"""Simple YAML renderer — standard library only (no PyYAML dependency)."""

from plugins import PluginError, Renderer, register


def _yaml_scalar(value) -> str:
    """Render a single scalar value as a YAML scalar string."""
    if value is None:
        return "null"
    if isinstance(value, bool):
        return "true" if value else "false"
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float):
        return str(value)
    # Treat everything else as a string
    s = str(value)
    # Quote if the value could be misinterpreted
    if s == "" or s in ("true", "false", "null", "yes", "no", "on", "off"):
        return f'"{s}"'
    if any(c in s for c in ":{}[]&*?|->!%@`,#"):
        return f'"{s}"'
    if s.startswith(('"', "'", "{", "[", "(", ">", "|", "&", "*")):
        return f'"{s}"'
    return s


def _yaml_value(value, indent: int) -> str:
    """Render a value (scalar or list) indented at the given level."""
    if isinstance(value, list):
        lines: list[str] = []
        prefix = "  " * indent
        for item in value:
            if isinstance(item, dict):
                # Multi-line dict inside a list
                first = True
                for k, v in item.items():
                    if first:
                        lines.append(f"{prefix}- {_yaml_scalar(k)}: {_yaml_value(v, 0)}")
                        first = False
                    else:
                        lines.append(f"{prefix}  {_yaml_scalar(k)}: {_yaml_value(v, 0)}")
            else:
                lines.append(f"{prefix}- {_yaml_value(item, 0)}")
        return "\n".join(lines)
    if isinstance(value, dict):
        lines: list[str] = []
        prefix = "  " * indent
        for k, v in value.items():
            lines.append(f"{prefix}{_yaml_scalar(k)}: {_yaml_value(v, indent)}")
        return "\n".join(lines)
    return _yaml_scalar(value)


@register("yaml")
class YamlRenderer(Renderer):
    def render(self, rows: list[dict]) -> str:
        if not isinstance(rows, list) or not rows:
            raise PluginError("yaml needs a non-empty list of dicts")
        if not all(isinstance(r, dict) for r in rows):
            raise PluginError("yaml needs a non-empty list of dicts")
        # Build a list-of-mappings YAML document
        lines: list[str] = []
        for row in rows:
            lines.append(_yaml_value(row, 0))
        return "\n".join(lines) + "\n"

